from typing import List

def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []

    result = []
    k = 3  # window size
    window = []

    for i in range(len(numbers)):
        if i >= k:
            window.pop(0)

        while window and numbers[i] >= numbers[window[-1]]:
            window.pop()

        window.append(i)

        if i >= k - 1:
            result.append(numbers[window[0]])

    return result

